head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[dataList > E > onaftercolumnfilterchange]<br/>DataList 모듈의 특정 Column 에 필터가 적용된 후에 발생합니다.",
    "validation" : [
        "바인드 된 GridView 의 useFilterList=true 이고 Header Cell 의 useFilter=true 이면 GridView 의 Header 에서 필터가 적용된 후 onaftercolumnfilterchange 이벤트가 발생합니다.",
        "바인드 된 GridView 의 useFilterList=false 이고 Header Cell 의 useFilter=true 이면 GridView 의 Header 에서 필터를 적용해도 onbeforecolumnfilterchange 이벤트가 발생하지 않습니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {   
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        $p.data.remove("target1");
    }

    if (typeof gridView1 !== 'undefined') {
        gridView1.remove();
    }    

    // 조건 설정       
    let properties = {
        useFilterList: con_useFilterList.getText(),
    };

    let cList = $c.gcm.createCList(properties);

    // // 이벤트 설정
    // let eList = $c.gcm.createEList([""]);       

    // target 생성
    let grp_comp = document.querySelector('.tc_group_basic');
    let strTarget = '';
    let strGridView = '';
    let strNameSpace = $c.gcm.getNameSpace();

    strTarget += '<w2:dataList ' + strNameSpace + ' id="target1" baseNode="list" repeatNode="map">';        
    strTarget += '<w2:columnInfo>';
    strTarget += '<w2:column id="col1" name="name1" dataType="text"></w2:column>';
    strTarget += '<w2:column id="col2" name="name2" dataType="text"></w2:column>';
    strTarget += '<w2:column id="col3" name="name3" dataType="text"></w2:column>';
    strTarget += '<w2:column id="col4" name="name4" dataType="text"></w2:column>';
    strTarget += '</w2:columnInfo>';
    strTarget += '<w2:data use="true">';
    strTarget += '<w2:row>';
    strTarget += '<col1><![CDATA[col1_1]]></col1>';
    strTarget += '<col2><![CDATA[col2_1]]></col2>';
    strTarget += '<col3><![CDATA[col3_1]]></col3>';
    strTarget += '<col4><![CDATA[col4_1]]></col4>';
    strTarget += '</w2:row>';
    strTarget += '<w2:row>';
    strTarget += '<col1><![CDATA[col1_2]]></col1>';
    strTarget += '<col2><![CDATA[col2_2]]></col2>';
    strTarget += '<col3><![CDATA[col3_2]]></col3>';
    strTarget += '<col4><![CDATA[col4_2]]></col4>';
    strTarget += '</w2:row>';
    strTarget += '<w2:row>';
    strTarget += '<col1><![CDATA[col1_3]]></col1>';
    strTarget += '<col2><![CDATA[col2_3]]></col2>';
    strTarget += '<col3><![CDATA[col3_3]]></col3>';
    strTarget += '<col4><![CDATA[col4_3]]></col4>';
    strTarget += '</w2:row>';
    strTarget += '<w2:row>';
    strTarget += '<col1><![CDATA[col1_4]]></col1>';
    strTarget += '<col2><![CDATA[col2_4]]></col2>';
    strTarget += '<col3><![CDATA[col3_4]]></col3>';
    strTarget += '<col4><![CDATA[col4_4]]></col4>';
    strTarget += '</w2:row>';
    strTarget += '</w2:data>';
    strTarget += '</w2:dataList>';       


    $p.data.create(strTarget);

    target1.bind("onbeforecolumnfilterchange ", function(e){ wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onbeforecolumnfilterchange =====");});
    target1.bind("onaftercolumnfilterchange", function(e){ wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onaftercolumnfilterchange=====");});

    // gridView 생성
    strGridView += '<w2:gridView ' + strNameSpace + ' ' + cList + ' sortable="true" rowStatusVisible="true" checkAllType="false" id="gridView1" dataList="target1" style="width:500px;height:300px;" ev:onsort="scwin.gridView1_onsort">';
    strGridView += '<w2:caption style="" id="caption1" value="this is a grid caption."></w2:caption>';
    strGridView += '<w2:header style="" id="header1">';
    strGridView += '<w2:row style="" id="row1">';
    strGridView += '<w2:column useFilter="true" width="100" style="" inputType="text" id="column1" value="name1"></w2:column>';
    strGridView += '<w2:column useFilter="true" width="100" style="" inputType="text" id="column2" value="name2"></w2:column>';
    strGridView += '<w2:column useFilter="true" width="100" style="" inputType="text" id="column3" value="name3"></w2:column>';
    strGridView += '<w2:column useFilter="true"  width="100" style="" inputType="text" id="column4" value="name4"></w2:column>';
    strGridView += '</w2:row>';
    strGridView += '</w2:header>';
    strGridView += '<w2:gBody style="" id="gBody1">';
    strGridView += '<w2:row style="" id="row2">';
    strGridView += '<w2:column width="70" style="" inputType="text" id="col1" value=""></w2:column>';
    strGridView += '<w2:column width="70" style="" inputType="text" id="col2" value=""></w2:column>';
    strGridView += '<w2:column width="70" style="" inputType="text" id="col3" value=""></w2:column>';
    strGridView += '<w2:column width="70" style="" inputType="text" id="col4" value=""></w2:column>';
    strGridView += '</w2:row>';
    strGridView += '</w2:gBody>';
    strGridView += '</w2:gridView>';   

    // gridView 생성
    scwin["gridView1"] = await $p.dynamicCreate(
        "gridView1",
        "gridView",
        strGridView,
        grp_comp
    );    
}
